package com.ethk3.novaonepro.strategyv2;
import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;
public final class RepairIssueTimelineR30Test {
    static Map<String,Object> m(Object... values){return RepairReportFactsR30Test.m(values);}
    @Test public void negativeAndCrossBootAreSeparateUnknownsNotFastSamples(){
        IssueTimelineR30.Row negative=new IssueTimelineR30.Row("SYNTHETIC").set(IssueTimelineR30.Stage.FIRST_OBSERVED,1000L,100L,"BOOT_A").set(IssueTimelineR30.Stage.SETTLED,2000L,99L,"BOOT_A");
        IssueTimelineR30.Row cross=new IssueTimelineR30.Row("SYNTHETIC_CROSS").set(IssueTimelineR30.Stage.FIRST_OBSERVED,1000L,100L,"BOOT_A").set(IssueTimelineR30.Stage.SETTLED,2000L,1000L,"BOOT_B");
        Map<?,?> s=(Map<?,?>)IssueTimelineR30.summarize(Arrays.asList(negative,cross)).get("observe_to_settled");assertNull(negative.elapsed(IssueTimelineR30.Stage.FIRST_OBSERVED,IssueTimelineR30.Stage.SETTLED));assertEquals(1,s.get("negativeMonotonicDifference"));assertEquals(1,s.get("crossBoot"));assertEquals(0,s.get("n"));assertNull(s.get("p95"));
    }
    @Test public void wallClockJumpCannotChangeMonotonicDuration(){IssueTimelineR30.Row row=new IssueTimelineR30.Row("SYNTHETIC").set(IssueTimelineR30.Stage.FIRST_OBSERVED,10000L,100L,"BOOT_A").set(IssueTimelineR30.Stage.SETTLED,1L,150L,"BOOT_A");assertEquals(Long.valueOf(50),row.elapsed(IssueTimelineR30.Stage.FIRST_OBSERVED,IssueTimelineR30.Stage.SETTLED));}
    @Test public void nestedBackfillScopePreservesActualLiveFetchAndRestoresAfterReturn(){assertEquals(IssueTimelineR30.EventRole.UNKNOWN,IssueTimelineWriterR30.requestRole());try(IssueTimelineWriterR30.RequestScope live=IssueTimelineWriterR30.requestScope(IssueTimelineR30.EventRole.LIVE)){try(IssueTimelineWriterR30.RequestScope history=IssueTimelineWriterR30.requestScope(IssueTimelineR30.EventRole.BACKFILL)){assertEquals(IssueTimelineR30.EventRole.LIVE,IssueTimelineWriterR30.requestRole());}}assertEquals(IssueTimelineR30.EventRole.UNKNOWN,IssueTimelineWriterR30.requestRole());}
    static Map<String,Object> draw(){return m("event_id","DRAW_A","event_role","LIVE","event_kind","DRAW","issue","BASE_A","draw_hash","EXACT_HASH_A","source_trace","SYNTHETIC_HTTP_A","wall_draw_committed",1020L,"mono_draw_committed",20L,"wall_first_observed",1010L,"mono_first_observed",10L,"boot_first_observed","BOOT_A","wall_settled",1021L,"mono_settled",21L,"boot_settled","BOOT_A","durable_wall",1025L,"durable_mono",25L,"durable_boot","BOOT_A","durable_stage","SETTLED","timing_boundary","CALLER_OBSERVED_SUCCESS_AFTER_SQLITE_COMMIT");}
    static Map<String,Object> prediction(){return m("event_id","PRED_B","event_role","LIVE","event_kind","PREDICTION","issue","TARGET_B","source_issue","BASE_A","source_draw_hash","EXACT_HASH_A","source_trace","SYNTHETIC_ATTEMPT_B","wall_next_requested",1030L,"mono_next_requested",30L,"boot_next_requested","BOOT_A","wall_next_frozen",1045L,"mono_next_frozen",45L,"boot_next_frozen","BOOT_A","wall_next_deadline",10000L,"durable_wall",1050L,"durable_mono",50L,"durable_boot","BOOT_A","durable_stage","NEXT_FROZEN","timing_boundary","CALLER_OBSERVED_SUCCESS_AFTER_SQLITE_COMMIT");}
    static ReportR27.R30Input view(List<Object> rows){Map<String,Object> data=m("timelineEventRows",rows);ReportSnapshotR30.timelineViewsR30(data);return new ReportR27.R30Input(m(),m("factsReadAt",12000L),data,Collections.emptyList());}
    @Test public void actualCommitObservationAndExactBaseIssueDetermineDurations(){ReportR27.R30Input in=view(Arrays.asList(draw(),prediction()));assertEquals(15.0,((Number)RepairReportFactsR30Test.metric(in,"M04").get("value")).doubleValue(),0);assertEquals(25.0,((Number)RepairReportFactsR30Test.metric(in,"M03").get("value")).doubleValue(),0);Map<?,?> row=(Map<?,?>)((List<?>)in.data.get("timeline")).get(1);assertEquals(45L,row.get("precommit_mono_next_frozen"));assertEquals(50L,row.get("mono_next_frozen"));assertEquals("DRAW_A",row.get("sourceSettlementEventId"));}
    @Test public void missingCommitObservationNeverUsesThePrecommitClock(){Map<String,Object> prediction=prediction();prediction.remove("durable_mono");ReportR27.R30Input in=view(Arrays.asList(draw(),prediction));assertNull(RepairReportFactsR30Test.metric(in,"M03").get("value"));assertNull(RepairReportFactsR30Test.metric(in,"M05").get("value"));assertEquals("UNKNOWN_DURABLE_OBSERVATION_MISSING",RepairReportFactsR30Test.metric(in,"M05").get("status"));}
    @Test public void wrongBaseHashDoesNotBorrowSomeOtherIssuesSettlement(){Map<String,Object> prediction=prediction();prediction.put("source_draw_hash","DIFFERENT_HASH");ReportR27.R30Input in=view(Arrays.asList(draw(),prediction));Map<?,?> row=(Map<?,?>)((List<?>)in.data.get("timeline")).get(1);assertNull(row.get("mono_settled"));assertEquals(20.0,((Number)RepairReportFactsR30Test.metric(in,"M03").get("value")).doubleValue(),0);}
}
